using System.Net.Sockets;

namespace Backroom.AppHost;

/// <summary>
/// Backing services for local development (see "Geliştirme ortamı ve güvenlik önlemleri" in docs/requirements.md).
/// Image versions are pinned; Bitnami images are not used. Passwords and keys are generated by Aspire and
/// stored in the AppHost's user secrets, never in the repository.
/// </summary>
internal static class DevelopmentServices
{
    public const string ValkeyImageTag = "9.1.3";
    public const string MailpitImageTag = "v1.32.0";
    public const string KeycloakImageTag = "26.8.1";
    public const string SeaweedFsImage = "chrislusf/seaweedfs";
    public const string SeaweedFsImageTag = "4.50";
    public const string LiveKitImage = "livekit/livekit-server";
    public const string LiveKitImageTag = "v1.13.11";
    public const string LiveKitApiKey = "backroom-dev";

    public const int MailpitSmtpPort = 1025;
    public const int MailpitUiPort = 8025;
    public const int MailpitMaxMessages = 500;
    public const int KeycloakPort = 8443;
    public const int SeaweedFsS3Port = 8333;
    public const int SeaweedFsContainerS3Port = 8333;
    public const int LiveKitHttpPort = 7880;
    public const int LiveKitRtcTcpPort = 7881;
    public const int LiveKitRtcUdpPort = 7882;

    public const string KeycloakRealm = "backroom";

    /// <summary>Adds the backing services; returns those the hosts are wired to.</summary>
    /// <remarks>An isolated run (<see cref="DevelopmentRun"/>) keeps no data and leaves out object storage and LiveKit.</remarks>
    public static DevelopmentResources AddDevelopmentServices(this IDistributedApplicationBuilder builder, DevelopmentRun run)
    {
        ArgumentNullException.ThrowIfNull(run);

        var postgres = builder.AddPostgres("postgres");

        var valkey = builder.AddValkey("valkey")
            .WithImageTag(ValkeyImageTag);

        var rabbitMq = builder.AddRabbitMQ("rabbitmq")
            .WithManagementPlugin();

        // With a trusted ASP.NET Core development certificate, Aspire mounts it into the container and
        // Keycloak is published over HTTPS on this port; without one, the same port serves plain HTTP.
        // The realm (clients, audience, test users alice@example.test and bob@example.test) is imported on
        // first start; its placeholders are filled from these variables. The test users' password is
        // generated and kept in user secrets (shown in the dashboard's parameters). Keycloak's email
        // goes to Mailpit (docs/adr/0008, item 7).
        var devUserPassword = builder.AddParameter(
            "dev-user-password",
            new GenerateParameterDefault { MinLength = 16, Special = false },
            secret: true,
            persist: true);

        // The control plane manages cell clients with this client's secret (docs/contracts/phase-1.md, "Cell registration").
        var controlPlaneAdminSecret = builder.AddParameter(
            "keycloak-control-plane-admin-secret",
            new GenerateParameterDefault { MinLength = 32, Special = false },
            secret: true,
            persist: true);

        var keycloak = builder.AddKeycloak("keycloak", port: KeycloakPort)
            .WithImageTag(KeycloakImageTag)
            .WithRealmImport("keycloak-dev")
            // Off: the account console and its API (account settings live in our app) and impersonation (no one may
            // act as another person); docs/adr/0009-keycloak-features.md. Deployments set the same.
            .WithEnvironment("KC_FEATURES_DISABLED", "account,account-api,impersonation")
            // The sign-in pages in the product's design, chosen by the realm's loginTheme. Not the server default:
            // that would also apply to the account, admin and email themes, which this theme does not have.
            .WithBindMount("keycloak-themes/backroom", "/opt/keycloak/themes/backroom", isReadOnly: true)
            .WithEnvironment("BACKROOM_DEV_USER_PASSWORD", devUserPassword)
            .WithEnvironment("BACKROOM_CONTROL_PLANE_ADMIN_SECRET", controlPlaneAdminSecret)
            .WithEnvironment("BACKROOM_SMTP_HOST", "mailpit")
            .WithEnvironment("BACKROOM_SMTP_PORT", MailpitSmtpPort.ToString(System.Globalization.CultureInfo.InvariantCulture));

        // Every non-production email goes here. Relay is never configured (docs/adr/0008).
        // The cap equals Mailpit's current default; it is set explicitly so a changed default cannot lift it.
        var mailpit = builder.AddMailPit("mailpit", httpPort: MailpitUiPort, smtpPort: MailpitSmtpPort)
            .WithImageTag(MailpitImageTag)
            .WithEnvironment("MP_MAX_MESSAGES", MailpitMaxMessages.ToString(System.Globalization.CultureInfo.InvariantCulture));

        var resources = new DevelopmentResources(keycloak, postgres, controlPlaneAdminSecret, rabbitMq, mailpit, valkey);
        if (run.Isolated)
        {
            return resources;
        }

        postgres.WithDataVolume();
        valkey.WithDataVolume();
        rabbitMq.WithDataVolume();
        keycloak.WithDataVolume();

        // S3-compatible object storage. No identities are configured, so the S3 API accepts anonymous
        // requests; it is published on localhost only.
        var seaweedFs = builder.AddContainer("seaweedfs", SeaweedFsImage, SeaweedFsImageTag);
        seaweedFs
            .WithArgs("server", "-dir=/data", "-s3", $"-s3.port={SeaweedFsContainerS3Port}")
            .WithVolume(VolumeNameGenerator.Generate(seaweedFs, "data"), "/data")
            .WithHttpEndpoint(port: SeaweedFsS3Port, targetPort: SeaweedFsContainerS3Port, name: "s3")
            .WithHttpHealthCheck("/", endpointName: "s3");

        // Local LiveKit in dev mode. Media uses a single UDP port; --node-ip makes the advertised
        // ICE candidates reachable from the host through Docker's port mapping.
        var liveKitSecret = builder.AddParameter(
            "livekit-api-secret",
            new GenerateParameterDefault { MinLength = 32, Special = false },
            secret: true,
            persist: true);

        builder.AddContainer("livekit", LiveKitImage, LiveKitImageTag)
            .WithArgs("--dev", "--bind", "0.0.0.0", "--node-ip", "127.0.0.1")
            .WithEnvironment("LIVEKIT_KEYS", ReferenceExpression.Create($"{LiveKitApiKey}: {liveKitSecret}"))
            .WithHttpEndpoint(port: LiveKitHttpPort, targetPort: 7880, name: "http", isProxied: false)
            .WithEndpoint(port: LiveKitRtcTcpPort, targetPort: 7881, name: "rtc-tcp", scheme: "tcp", isProxied: false)
            .WithEndpoint(port: LiveKitRtcUdpPort, targetPort: 7882, name: "rtc-udp", scheme: "udp", protocol: ProtocolType.Udp, isProxied: false)
            .WithHttpHealthCheck("/", endpointName: "http");

        return resources;
    }
}
